    29	pub(crate) fn run(builder: tauri::Builder<tauri::Wry>) {
    30	    let app = builder
    31	        .on_window_event(|window, event| {
    32	            #[cfg(not(mobile))]
    33	            if let tauri::WindowEvent::CloseRequested { api, .. } = event {
    34	                api.prevent_close();
    35	                begin_native_close(window.app_handle());
    36	            }
    37	            #[cfg(mobile)]
    38	            let _ = (window, event);
    39	        })
    40	        .setup(|app| {
    41	            #[cfg(mobile)]
    42	            let mode = "fixture".to_owned();
    43	            #[cfg(not(mobile))]
    44	            let mode = match std::env::var_os("EMAIL_OS_MODE") {
    45	                Some(value) => value
    46	                    .into_string()
    47	                    .map_err(|_| "EMAIL_OS_MODE must be valid UTF-8")?,
    48	                None => "fixture".to_owned(),
    49	            };
    50	            let app_data_dir = app.path().app_data_dir()?;
    51	            let (core, profile_dir) = match mode.as_str() {
    52	                "fixture" => open_fixture_core(&app_data_dir)?,
    53	                "gmail" => {
    54	                    let profile_dir = app_data_dir.join("gmail-profile");
    55	                    let provider = LiveGmailProvider::from_env(Arc::new(KeychainSecrets::new()))?;
    56	                    let provider: Arc<dyn mail_core::gmail::types::GmailProvider> =
    57	                        Arc::new(provider);
    58	                    (GmailCore::open(&profile_dir, provider)?, profile_dir)
    59	                }
    60	                _ => return Err("EMAIL_OS_MODE must be fixture or gmail".into()),
    61	            };
    62	            let drafts = DraftCore::open(profile_dir.join("local-drafts"))?;
    63	            // The one-time retirement of a legacy fixture database; a no-op in
    64	            // Gmail mode and on a fresh fixture profile.
    65	            app.manage(Arc::new(if mode == "fixture" {
    66	                FixtureTransition::new(&profile_dir)
    67	            } else {
    68	                FixtureTransition::inactive()
    69	            }));
    70	
    71	            let handle = app.handle().clone();
    72	            app.manage(AppState::new(core, drafts, move || {
    73	                // Notifications are best-effort hints; the frontend refetches persisted state.
    74	                let _ = handle.emit("mailbox_changed", ());
    75	            }));
    76	            Ok(())
    77	        })
    78	        .build(tauri::generate_context!())
    79	        .expect("failed to build the email-os shell");
    80	
    81	    app.run(|app_handle, event| match event {
    82	        #[cfg(not(mobile))]
    83	        RunEvent::ExitRequested { api, .. } => {
    84	            let authorized = app_handle
    85	                .try_state::<AppState>()
    86	                .and_then(|state| {
    87	                    state
    88	                        .close_gate
    89	                        .lock()
    90	                        .ok()
    91	                        .map(|mut gate| gate.take_exit_authorization())
    92	                })
    93	                .unwrap_or(false);
    94	            if !authorized {
    95	                api.prevent_exit();
    96	                begin_native_close(app_handle);
    97	            }
    98	        }
    99	        #[cfg(not(mobile))]
   100	        RunEvent::Exit => {
   101	            if let Some(state) = app_handle.try_state::<AppState>() {
   102	                state.core.stop();
   103	            }
   104	        }
   105	        _ => {}
   106	    });
   107	}
