   123	        let profile = dir.path().join("fixture-profile");
   124	        std::fs::create_dir_all(&profile).unwrap();
   125	        std::fs::write(profile.join("mail.db"), LEGACY_MAIL_DB).unwrap();
   126	        let (core, opened) = open_fixture_core(dir.path()).unwrap();
   127	        assert_eq!(core.account_status().unwrap().mode, MailMode::Fixture);
   128	        assert_eq!(opened, profile);
   129	        assert!(profile.join("synthetic-provider.db").exists());
   130	        assert!(profile.join("gmail.db").exists());
   131	        assert_eq!(
   132	            std::fs::read(profile.join("mail.db")).unwrap(),
   133	            LEGACY_MAIL_DB
   134	        );
   135	        assert!(!profile.join("mail.db-wal").exists() && !profile.join("mail.db-shm").exists());
   136	        // The fixture profile has a single writer.
   137	        assert!(matches!(
   138	            open_fixture_core(dir.path()),
   139	            Err(error) if error.to_string().contains("another writer")
