   144	    /// The real startup order: the synthetic core is open (new files), then the
   145	    /// disclosed transition retires the legacy database beside it. Drafts keep
   146	    /// their account and their conversation/message references.
   147	    #[test]
   148	    fn retiring_the_legacy_database_beside_a_live_core_keeps_drafts_and_the_core_working() {
   149	        let dir = temp_profile("synthetic-transition");
   150	        let profile = dir.path().join("fixture-profile");
   151	        std::fs::create_dir_all(&profile).unwrap();
   152	        std::fs::write(profile.join("mail.db"), LEGACY_MAIL_DB).unwrap();
   153	        let (core, _) = open_fixture_core(dir.path()).unwrap();
   154	
   155	        // A reply draft written under the legacy core (same account, same IDs).
   156	        let drafts = DraftCore::open(profile.join("local-drafts")).unwrap();
   157	        let account = core.active_account().unwrap();
   158	        let detail = core.get_conversation(&conv("conv-01")).unwrap();
   159	        let source = detail.messages.last().unwrap().id.clone();
   160	        let receipt = drafts
   161	            .create_draft(
   162	                &account,
   163	                &mail_core::drafts::types::CreateDraft {
   164	                    request_id: "legacy-draft".into(),
   165	                    source: DraftSource::Reply {
   166	                        conversation: conv("conv-01"),
   167	                        source_message_id: source.clone(),
   168	                    },
   169	                    initial_content: None,
   170	                },
   171	                Some(&detail),
   172	            )
   173	            .unwrap();
   174	        let draft_files: Vec<_> = std::fs::read_dir(profile.join("local-drafts"))
   175	            .unwrap()
   176	            .map(|e| e.unwrap().file_name())
   177	            .collect();
   178	
   179	        let transition = FixtureTransition::new(&profile);
   180	        assert_eq!(
   181	            transition.status().unwrap().state,
   182	            mail_core::fixture_transition::FixtureTransitionState::NeedsDisclosure
   183	        );
   184	        let done = transition.accept().unwrap();
   185	        assert_eq!(
   186	            done.state,
   187	            mail_core::fixture_transition::FixtureTransitionState::Done
   188	        );
   189	        assert!(!profile.join("mail.db").exists());
   190	        assert_eq!(
   191	            std::fs::read_dir(profile.join("backups")).unwrap().count(),
   192	            1
   193	        );
   194	
   195	        // The core never noticed; drafts and their references are intact.
   196	        assert_eq!(core.account_status().unwrap().sync.cached_conversations, 18);
   197	        let again: Vec<_> = std::fs::read_dir(profile.join("local-drafts"))
   198	            .unwrap()
   199	            .map(|e| e.unwrap().file_name())
   200	            .collect();
   201	        assert_eq!(draft_files, again, "local-drafts untouched");
   202	        let draft = drafts.get_draft(&account, &receipt.draft_ref).unwrap();
   203	        assert_eq!(draft.revision, receipt.revision);
   204	        let reply = load_validated_reply_context(&core, &conv("conv-01"), &source).unwrap();
   205	        assert_eq!(reply.reply_context.unwrap().source_message_id, source);
   206	        core.stop();
   207	    }
