     9	use serde::{Deserialize, Serialize};
    10	
    11	use crate::error::MailError;
    12	
    13	/// Redacted credential bundle. Serialized as JSON into the secret store;
    14	/// contents are never logged, serialized to IPC, or included in errors.
    15	#[derive(Clone, PartialEq, Eq, Serialize, Deserialize)]
    16	#[serde(rename_all = "camelCase")]
    17	pub struct TokenBundle {
    18	    pub access_token: String,
    19	    /// Preserved when Google omits it in a refresh response.
    20	    pub refresh_token: Option<String>,
    21	    /// Absolute access-token expiry, epoch milliseconds.
    22	    pub expires_at_epoch_ms: i64,
    23	    /// Stable account id, set after profile discovery.
    24	    pub account_id: Option<String>,
    25	    /// Account email, set after profile discovery.
    26	    pub email: Option<String>,
    27	    /// True only after Google explicitly returned `gmail.modify` for this
    28	    /// bound account. Missing in legacy bundles and therefore denied.
    29	    #[serde(default)]
    30	    pub gmail_modify_granted: bool,
    31	}
