    52	/// Secret store seam. Implementations must be injectable for tests; the
    53	/// production implementation is [`KeychainSecrets`].
    54	pub trait Secrets: Send + Sync {
    55	    /// Loads the stored bundle, or `None` when no credentials exist.
    56	    fn load(&self) -> Result<Option<TokenBundle>, MailError>;
    57	    /// Replaces the stored bundle.
    58	    fn store(&self, bundle: &TokenBundle) -> Result<(), MailError>;
    59	    /// Deletes the stored bundle. Disconnect must remove credentials locally.
    60	    fn clear(&self) -> Result<(), MailError>;
    61	}
    62	
    63	/// macOS Keychain credential store. Any Keychain failure fails closed:
    64	/// the caller receives [`MailError::SecretsUnavailable`], never a fallback.
    65	pub struct KeychainSecrets;
    66	
    67	#[cfg(target_os = "macos")]
    68	const SECRETS_SERVICE: &str = "mail-core-gmail";
    69	#[cfg(target_os = "macos")]
    70	const SECRETS_USER: &str = "single-profile";
    71	
    72	impl KeychainSecrets {
    73	    pub fn new() -> Self {
    74	        Self
    75	    }
    76	}
    77	
    78	impl Default for KeychainSecrets {
    79	    fn default() -> Self {
    80	        Self::new()
    81	    }
    82	}
    83	
    84	#[cfg(target_os = "macos")]
    85	impl Secrets for KeychainSecrets {
    86	    fn load(&self) -> Result<Option<TokenBundle>, MailError> {
    87	        let entry = keyring::Entry::new(SECRETS_SERVICE, SECRETS_USER)
    88	            .map_err(|_| MailError::SecretsUnavailable)?;
    89	        match entry.get_password() {
    90	            Ok(json) => Some(
    91	                serde_json::from_str::<TokenBundle>(&json)
    92	                    .map_err(|_| MailError::SecretsUnavailable),
    93	            )
    94	            .transpose(),
    95	            Err(keyring::Error::NoEntry) => Ok(None),
    96	            Err(_) => Err(MailError::SecretsUnavailable),
    97	        }
    98	    }
    99	
   100	    fn store(&self, bundle: &TokenBundle) -> Result<(), MailError> {
   101	        let entry = keyring::Entry::new(SECRETS_SERVICE, SECRETS_USER)
   102	            .map_err(|_| MailError::SecretsUnavailable)?;
   103	        let json = serde_json::to_string(bundle).map_err(|_| MailError::SecretsUnavailable)?;
   104	        entry
   105	            .set_password(&json)
   106	            .map_err(|_| MailError::SecretsUnavailable)
   107	    }
   108	
   109	    fn clear(&self) -> Result<(), MailError> {
   110	        let entry = keyring::Entry::new(SECRETS_SERVICE, SECRETS_USER)
   111	            .map_err(|_| MailError::SecretsUnavailable)?;
   112	        match entry.delete_credential() {
   113	            Ok(()) | Err(keyring::Error::NoEntry) => Ok(()),
   114	            Err(_) => Err(MailError::SecretsUnavailable),
   115	        }
   116	    }
   117	}
