155	/// base64url alphabet without padding; every character is a valid PKCE
156	/// verifier character.
157	const PKCE_ALPHABET: &[u8] = b"REDACTED";
158	
159	fn random_b64url(len: usize) -> String {
160	    let mut rng = rand::thread_rng();
161	    let mut bytes = vec![0u8; len];
162	    rng.fill_bytes(&mut bytes);
163	    bytes
164	        .iter()
165	        .map(|b| PKCE_ALPHABET[*b as usize % PKCE_ALPHABET.len()] as char)
166	        .collect()
167	}
