333	/// Reads one bounded HTTP request, polling cancellation and the shared OAuth
334	/// deadline between socket reads so a trickling peer cannot hold sign-in open.
335	fn read_request(
336	    stream: &mut std::net::TcpStream,
337	    deadline: Instant,
338	    cancel: &CancelToken,
339	) -> Result<Option<String>, MailError> {
340	    let mut buf = Vec::new();
341	    let mut chunk = [0u8; 1024];
342	    loop {
343	        if cancel.is_cancelled() {
344	            return Err(MailError::AuthCancelled);
345	        }
346	        if Instant::now() >= deadline {
347	            return Err(MailError::AuthFailed);
348	        }
349	        if buf.windows(4).any(|w| w == b"\r\n\r\n") || buf.len() >= MAX_REQUEST_BYTES {
350	            break;
351	        }
352	        match stream.read(&mut chunk) {
353	            Ok(0) => break,
354	            Ok(n) => buf.extend_from_slice(&chunk[..n]),
355	            Err(error)
356	                if matches!(
357	                    error.kind(),
358	                    std::io::ErrorKind::WouldBlock | std::io::ErrorKind::TimedOut
359	                ) => {}
360	            Err(error) if error.kind() == std::io::ErrorKind::Interrupted => {}
361	            Err(_) => break,
362	        }
363	    }
364	    if !buf.windows(4).any(|window| window == b"\r\n\r\n") {
365	        return Ok(None);
366	    }
367	    Ok(Some(String::from_utf8_lossy(&buf).into_owned()))
368	}
